`timescale 1ns/1ps
module tb_mlkem_sample_ntt;reg clk=0,rst_n=0,start=0,ordy=1,was_stalled=0;reg[255:0]seed;reg[7:0]i0,i1;wire busy,done,error,ov;wire[11:0]oc;wire[7:0]oi;wire[1:0]dom;wire[31:0]groups,acc,rej;integer fd,rc,v,i,got,checks=0,eg,er,cycles,mincycles=999999,maxcycles=0,sumcycles=0,ming=999999,maxg=0,sumg=0,stallcycle=0;reg[11:0]exp[0:255],held_c;reg[7:0]held_i;string file;always#5 clk=~clk;mlkem_sample_ntt dut(clk,rst_n,start,seed,i0,i1,1'b0,272'd0,busy,done,error,ov,ordy,oc,oi,dom,groups,acc,rej);
 initial begin if(!$value$plusargs("VECTOR_FILE=%s",file))$fatal(1,"VECTOR_FILE");fd=$fopen(file,"r");repeat(3)@(negedge clk);rst_n=1;for(v=0;v<64;v=v+1)begin rc=$fscanf(fd,"%h %h %h %d %d\n",i0,i1,seed,eg,er);for(i=0;i<256;i=i+1)rc=$fscanf(fd,"%h\n",exp[i]);@(negedge clk);start=1;@(negedge clk);start=0;got=0;cycles=0;while(!done)begin @(negedge clk);cycles=cycles+1;if(cycles>10000)$fatal(1,"watchdog v=%0d",v);end if(error||got!=256||groups!=eg)$fatal(1,"status v=%0d groups=%0d/%0d rej=%0d/%0d",v,groups,eg,rej,er);if(cycles<mincycles)mincycles=cycles;if(cycles>maxcycles)maxcycles=cycles;sumcycles=sumcycles+cycles;if(groups<ming)ming=groups;if(groups>maxg)maxg=groups;sumg=sumg+groups;end
  @(negedge clk);start=1;@(negedge clk);start=0;got=0;repeat(300)@(negedge clk);rst_n=0;@(negedge clk);if(busy||done||ov)$fatal(1,"reset cancel");rst_n=1;@(negedge clk);start=1;@(negedge clk);start=0;got=0;while(!done)@(negedge clk);if(error||got!=256||groups!=eg)$fatal(1,"restart");
  $display("PASS tb_mlkem_sample_ntt vectors=64 coeff_checks=%0d groups_min=%0d groups_max=%0d groups_avg=%0d cycles_min=%0d cycles_max=%0d cycles_avg=%0d reset_restart=PASS backpressure=PASS",checks,ming,maxg,sumg/64,mincycles,maxcycles,sumcycles/64);$finish;end
 always@(negedge clk)if(rst_n)begin stallcycle=stallcycle+1;ordy=(stallcycle%9)!=4;end
 always@(posedge clk)begin if(!rst_n)was_stalled=0;else begin if(was_stalled&&(!ov||oc!==held_c||oi!==held_i))$fatal(1,"stalled output changed");was_stalled=ov&&!ordy;if(ov&&!ordy)begin held_c=oc;held_i=oi;end if(ov&&ordy)begin if(got>=256||oi!==got[7:0]||oc!==exp[got]||oc>=3329||dom!=2'b10)$fatal(1,"v=%0d i=%0d exp=%0d got=%0d parser_count=%0d qcount=%0d parser_busy=%b parent_done=%b",v,got,exp[got],oc,dut.p.count,dut.p.qcount,dut.p.busy,done);got=got+1;checks=checks+1;end end end endmodule
